WHO = {'column': [('psillfools', 311446), ('norllellyvi', 0), ('muslfools', 311574), ('bridgepy', 311702), ('solkllben', 311702), ('durollyvi', 0), ('aprilellyvi', 311951), ('muut', 311951)], 'tree': [('dukkllgepy', 311510), ('aprilfools', 0), ('aprillledum', 311823), ('psilllkize', 312968), ('solkeelledum', 313409), ('dukkllgepy', 314362), ('durodlsof', 0), ('duroanor', 314419)], 'bridge': [('norlllelefya', 311702), ('queyfllefya', 311759), ('maeelwei', 0), ('norllldmicro', 312271), ('queyfllefya', 0), ('maeelwei', 313032), ('alphafoldmicro', 315565), ('solkllllefya', 316578)], 'temple': [('duroanor', 312015), ('ashllgepy', 313089), ('queyfllefya', 316642), ('norlleeanor', 317723), ('muut', 318861), ('ashllgepy', 0), ('duroanor', 323359)], 'tower': [('solor', 0), ('aprilellyvi', 313217), ('duroanor', 313217), ('norllelefya', 0), ('loorfelor', 0), ('durollyvi', 0), ('loormae', 319806), ('norllellyvi', 322285)], 'manor': [('ashlldlsof', 0), ('durodlsof', 316514), ('psiloceyeben', 0), ('solkeellyvi', 318035), ('eindlsof', 320567), ('rensleeyeben', 325364)]}

EPI_RX = re.compile(
    r"^(?:what (?:has|have) (?P<a>[\w'\- ]{2,24}?) (?:done|been doing)"
    r"|what happened (?:with|to) (?P<b>[\w'\- ]{2,24}?))[?.! ]*$", re.I)
WHO_RX = re.compile(
    r"^who (?:built|made|raised) (?:a |an |the )?(?P<k>[\w \-]{2,24}?)[?.! ]*$", re.I)


class OracleReleaseRuntimeW6(OracleReleaseRuntimeW4):
    """Base + episodic recall. Fires only on bound episodes; else the chain answers."""

    def chat(self, text: str, session_id: str = "default") -> dict:
        s = " ".join(str(text).strip().split())
        m = EPI_RX.match(s)
        if m:
            actor = (m.group("a") or m.group("b") or "").strip().lower()
            eps = EPI.get(actor)
            if eps:
                bits = "; ".join(f"at tick {t} {v} {o}" for t, v, o in eps[-5:])
                pending = getattr(self, "_pending_conversion", None)
                if pending is None:
                    pending = self._pending_conversion = {}
                pending[session_id] = {"construction": "EPISODIC_RECALL",
                                        "from": s[:80], "to": f"episodes({actor})",
                                        "produced_by": "oracle_fold_worker_v4"}
                return {"status": "answered", "path": "worker:episodic",
                         "response": f"The record holds for {actor}: {bits}. "
                                     f"[world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "actor": actor,
                                         "episodes": len(eps)},
                         "latency_ms": 1}
        w = WHO_RX.match(s)
        if w:
            kind = w.group("k").strip().lower()
            hits = WHO.get(kind) or WHO.get(kind.rstrip("s"))
            if hits:
                bits = ", ".join(f"{a} (tick {t})" for a, t in hits[-4:])
                return {"status": "answered", "path": "worker:episodic_who",
                         "response": f"By the world record, {kind}s were raised by "
                                     f"{bits}. [world_ledger_ew2]",
                         "provenance": {"kind": "episodic_ledger", "object": kind},
                         "latency_ms": 1}
        return super().chat(s, session_id)
